$ cat Direct.java
import java.nio.ByteBuffer;
import java.util.*;
public class Direct {
    public static void main(String[] a) throws Exception {
        boolean direct = a[0].equals("direct");
        int mb = Integer.parseInt(a[1]);
        List<ByteBuffer> keep = new ArrayList<>();
        for (int i = 0; i < mb; i++)
            keep.add(direct ? ByteBuffer.allocateDirect(1<<20) : ByteBuffer.allocate(1<<20));
        Runtime r = Runtime.getRuntime();
        System.out.printf("%s %dMB  heapUsed=%dMB%n", a[0], mb,
            (r.totalMemory()-r.freeMemory())>>20);
    }
}

# --- 1) 같은 300MB, 힙 안과 힙 밖 ---

$ java -Xmx1g -cp out Direct heap 300
heap 300MB  heapUsed=601MB

$ java -Xmx1g -cp out Direct direct 300
direct 300MB  heapUsed=1MB          <- 300MB 를 잡았는데 힙은 1MB

# --- 2) 그러면 그 300MB 는 어디 있나 ---

$ java -Xmx1g -XX:NativeMemoryTracking=summary -cp out Direct direct 300 &
$ jcmd <pid> VM.native_memory summary
Total: reserved=2866232KB, committed=558904KB
-                 Java Heap (reserved=1048576KB, committed=133120KB)
-                     Other (reserved=307200KB, committed=307200KB)
                                                      ^^^^^^^^^ 정확히 300MB

